passos.comando:
-- no STANDBY:
SELECT * FROM v$archive_gap;
SELECT thread#, MAX(sequence#) AS ultima_aplicada
FROM   v$archived_log WHERE applied = 'YES' GROUP BY thread#;

-- no PRIMARIO:
SELECT thread#, MIN(sequence#) AS menor_em_disco, MAX(sequence#) AS maior
FROM   v$archived_log
WHERE  deleted = 'NO' AND standby_dest = 'NO' GROUP BY thread#;
SELECT thread#, MAX(sequence#) AS sequencia_atual FROM v$log GROUP BY thread#;

-- no STANDBY:
SELECT status, COUNT(*) FROM v$datafile_header GROUP BY status;
SELECT file#, status, error FROM v$datafile_header WHERE error IS NOT NULL;
SELECT * FROM v$recover_file;

-- tamanho, para dimensionar o que um DUPLICATE custaria:
SELECT ROUND(SUM(bytes)/1024/1024/1024,1) AS db_gb FROM v$datafile;

dgmgrl /
  SHOW DATABASE <standby>;
  EDIT DATABASE <standby> SET STATE='APPLY-OFF';
  SHOW DATABASE <standby>;

-- confirmar no sqlplus que o MRP morreu:
SELECT process, status FROM v$managed_standby WHERE process LIKE 'MRP%';

rman target /
RESTORE STANDBY CONTROLFILE FROM SERVICE '<primario>';
ALTER DATABASE MOUNT STANDBY DATABASE;

-- re-catalogar os datafiles que ja existem no standby:
CATALOG START WITH '+<DISKGROUP>/<DB>/DATAFILE/' NOPROMPT;
SWITCH DATABASE TO COPY;

rman target /
SHOW ALL;
CONFIGURE DEFAULT DEVICE TYPE TO DISK;
SHOW DEFAULT DEVICE TYPE;

# arquivo de comandos (fica como registro do que foi executado):
cat rollforward.rman
RUN {
  ALLOCATE CHANNEL c1 DEVICE TYPE DISK;
  ALLOCATE CHANNEL c2 DEVICE TYPE DISK;
  ALLOCATE CHANNEL c3 DEVICE TYPE DISK;
  ALLOCATE CHANNEL c4 DEVICE TYPE DISK;
  RECOVER DATABASE FROM SERVICE <primario>;
}

nohup rman target / cmdfile=rollforward.rman log=rollforward.log > /dev/null 2>&1 &

# acompanhar:
tail -f rollforward.log
SELECT sid, opname, ROUND(sofar/NULLIF(totalwork,0)*100,1) AS pct
FROM   v$session_longops WHERE totalwork > 0 AND sofar < totalwork;

SELECT (SELECT COUNT(*) FROM v$datafile)        AS no_controlfile,
       (SELECT COUNT(*) FROM v$datafile_header) AS com_header FROM dual;

SELECT con_id, COUNT(*) AS qtd,
       MIN(checkpoint_change#) AS scn_min,
       MAX(checkpoint_change#) AS scn_max
FROM   v$datafile_header GROUP BY con_id ORDER BY con_id;

SELECT file#, con_id, checkpoint_change#, status
FROM   v$datafile_header WHERE checkpoint_change# < <scn_novo> ORDER BY file#;

dgmgrl /
  EDIT DATABASE <standby> SET STATE='APPLY-ON';
  SHOW DATABASE <standby>;

-- confirmar o MRP e a ausencia de gap:
SELECT process, status, thread#, sequence# FROM v$managed_standby WHERE process LIKE 'MRP%';
SELECT * FROM v$archive_gap;
SELECT name, value, time_computed FROM v$dataguard_stats WHERE name LIKE '%lag%';

# voltar ao modo configurado (ex.: Active Data Guard):
srvctl stop database  -d <standby>
srvctl start database -d <standby>

-- no PRIMARIO:
RMAN> SHOW ARCHIVELOG DELETION POLICY;
RMAN> CONFIGURE ARCHIVELOG DELETION POLICY TO APPLIED ON ALL STANDBY;
